sed -i 's#^DATABASE_URL=.*#DATABASE_URL="postgresql://eval_rw:eval_rw@postgres:5432/llmapi_eval?serverVersion=17\&charset=utf8"#' .env && grep DATABASE_URL .env && mkdir -p src/JsonApi src/Repository src/Service src/Payment src/EventListener src/OpenApi && cat > start.sh <<'EOF'
#!/bin/sh
# Starts the Bookshop API on http://localhost:8089. Stop it by killing this process.
set -e
cd "$(dirname "$0")"

export APP_ENV=prod
export APP_DEBUG=0
export APP_SECRET="${APP_SECRET:-bookshop-local-secret}"
export DATABASE_URL="postgresql://eval_rw:eval_rw@postgres:5432/llmapi_eval?serverVersion=17&charset=utf8"

if [ ! -f vendor/autoload_runtime.php ]; then
    composer install --no-interaction --no-progress
fi

php bin/console cache:warmup > /dev/null

export PHP_CLI_SERVER_WORKERS=8
exec php -S 0.0.0.0:8089 -t public public/index.php
EOF
chmod +x start.sh && cat > src/JsonApi/ApiException.php <<'EOF'
<?php

namespace App\JsonApi;

use Symfony\Component\HttpFoundation\Response;

/**
 * A request failure, rendered as a JSON:API error document.
 */
final class ApiException extends \RuntimeException
{
    /**
     * @param list<array<string, mixed>> $errors
     * @param array<string, string>      $headers
     */
    public function __construct(
        private readonly array $errors,
        private readonly array $headers = [],
    ) {
        parent::__construct((string) ($errors[0]['detail'] ?? 'Error'));
    }

    public static function status(int $status, string $detail, array $headers = []): self
    {
        return new self([self::error($status, $detail)], $headers);
    }

    public static function parameter(string $name, string $detail): self
    {
        return new self([self::error(400, $detail, ['parameter' => $name])]);
    }

    /**
     * @return list<array<string, mixed>>
     */
    public function errors(): array
    {
        return $this->errors;
    }

    public function status_(): int
    {
        return (int) $this->errors[0]['status'];
    }

    /**
     * @return array<string, string>
     */
    public function headers(): array
    {
        return $this->headers;
    }

    /**
     * @param array<string, string> $source
     *
     * @return array<string, mixed>
     */
    public static function error(int $status, string $detail, array $source = []): array
    {
        $error = [
            'status' => (string) $status,
            'title' => Response::$statusTexts[$status] ?? 'Error',
            'detail' => $detail,
        ];
        if ([] !== $source) {
            $error['source'] = $source;
        }

        return $error;
    }
}
EOF
echo ok

sed -i 's/public function status_(): int/public function statusCode(): int/' src/JsonApi/ApiException.php && cat > src/JsonApi/Document.php <<'EOF'
<?php

namespace App\JsonApi;

use Symfony\Component\HttpFoundation\Request;
use Symfony\Component\HttpFoundation\Response;

/**
 * Builds JSON:API responses.
 */
final class Document
{
    public const MEDIA_TYPE = 'application/vnd.api+json';

    /**
     * @param array<string, mixed>  $body
     * @param array<string, string> $headers
     */
    public static function respond(array $body, int $status = 200, array $headers = []): Response
    {
        $json = json_encode(
            ['jsonapi' => ['version' => '1.1']] + $body,
            JSON_THROW_ON_ERROR | JSON_UNESCAPED_SLASHES | JSON_UNESCAPED_UNICODE,
        );

        return new Response($json, $status, ['Content-Type' => self::MEDIA_TYPE] + $headers);
    }

    /**
     * Rejects a request body whose media type is not JSON:API.
     */
    public static function requireMediaType(Request $request): void
    {
        $type = strtolower(trim(explode(';', (string) $request->headers->get('Content-Type', ''))[0]));
        if (self::MEDIA_TYPE !== $type) {
            throw ApiException::status(415, 'Content-Type must be application/vnd.api+json.');
        }
    }

    /**
     * Decodes a JSON object request body.
     *
     * @return array<string, mixed>
     */
    public static function decodeBody(Request $request): array
    {
        try {
            $decoded = json_decode($request->getContent(), true, 512, JSON_THROW_ON_ERROR);
        } catch (\JsonException) {
            throw ApiException::status(400, 'The request body is not valid JSON.');
        }
        if (!\is_array($decoded)) {
            throw ApiException::status(400, 'The request body must be a JSON object.');
        }

        return $decoded;
    }
}
