mkdir -p /tmp/bookshop-tests && cat > /tmp/bookshop-tests/snapshot.php <<'EOF'
<?php
// usage: php snapshot.php save|restore
$p = new PDO('pgsql:host=postgres;port=5432;dbname=llmapi_eval', 'eval_rw', 'eval_rw', [PDO::ATTR_ERRMODE => PDO::ERRMODE_EXCEPTION]);
$file = '/tmp/bookshop-tests/snapshot.json';
if ($argv[1] === 'save') {
    $s = [];
    foreach (['book', 'purchase', 'purchase_line'] as $t) {
        $s[$t] = $p->query("select * from $t order by id")->fetchAll(PDO::FETCH_ASSOC);
    }
    foreach (['book_id_seq', 'purchase_id_seq', 'purchase_line_id_seq'] as $q) {
        $s[$q] = $p->query("select last_value, is_called from $q")->fetch(PDO::FETCH_ASSOC);
    }
    file_put_contents($file, json_encode($s));
    echo "saved\n";
} else {
    $s = json_decode(file_get_contents($file), true);
    $p->exec('DELETE FROM purchase_line');
    $p->exec('DELETE FROM purchase');
    foreach ($s['purchase'] as $r) {
        $p->prepare('INSERT INTO purchase (id, customer_id, created_at, total_cents) VALUES (?,?,?,?)')->execute([$r['id'], $r['customer_id'], $r['created_at'], $r['total_cents']]);
    }
    foreach ($s['purchase_line'] as $r) {
        $p->prepare('INSERT INTO purchase_line (id, purchase_id, book_id, quantity, unit_price_cents) VALUES (?,?,?,?,?)')->execute([$r['id'], $r['purchase_id'], $r['book_id'], $r['quantity'], $r['unit_price_cents']]);
    }
    foreach ($s['book'] as $r) {
        $p->prepare('UPDATE book SET title=?, author_id=?, published=?, price_cents=?, published_at=?, stock=? WHERE id=?')->execute([$r['title'], $r['author_id'], $r['published'] === 't' || $r['published'] === true ? 'true' : 'false', $r['price_cents'], $r['published_at'], $r['stock'], $r['id']]);
    }
    foreach (['book_id_seq' => 'book', 'purchase_id_seq' => 'purchase', 'purchase_line_id_seq' => 'purchase_line'] as $q => $t) {
        $v = $s[$q];
        $p->query("select setval('$q', {$v['last_value']}, " . ($v['is_called'] === 't' || $v['is_called'] === true ? 'true' : 'false') . ")");
    }
    echo "restored\n";
}
EOF
cd /tmp/bookshop-tests && php snapshot.php save && which jq; php -r 'echo "x\n";'

